from lib import *
S = SS('v51')
steps = [
    step("TTL 决定摘掉的实例多久不再被访问。web.svc.local 有 3 个 SRV 目标,50 个请求/秒发 14 秒共 700 个,把第 3 个后端从 DNS 删掉并立刻停掉它,删除时刻 4.0 / 4.7 / 5.4 s 各做一次(错开缓存过期的相位)。遵守 TTL 的缓存:TTL 2 s,错误请求 0 / 19 / 13 个,DNS 查询 7 次;TTL 5 s,19 / 4 / 83 个,查询 3 次;TTL 10 s,105 / 90 / 83 个,查询 2 次。启动时解析一次、之后一直用:168 个错误,从 4.0 s 一直错到 13.9 s,DNS 查询 1 次。不缓存(每个请求解析一次):0 个错误,DNS 查询 700 次。TTL 越长错误越多(约三分之一的请求打到已停掉的后端),TTL 越短 DNS 查询越多。", t=tl(S(1)), mark=lidx(S(1), 'TTL 10 s', '启动时'), done=lidx(S(1), 'TTL 2 s', 'TTL 5 s', '不缓存'), b=bars([['TTL 2 s:错误请求(最多)', 19, '0 / 19 / 13'], ['TTL 10 s:错误请求(最多)', 105, '105 / 90 / 83'], ['解析一次:错误请求', 168, '168(一直错到结束)'], ['不缓存:DNS 查询数', 700, '700(错误 0)']], 700, done=[0, 3], mark=[1, 2]), kv=KV([['TTL 2 s', '错误 0~19 个,DNS 查询 7 次'], ['TTL 10 s', '错误 83~105 个,查询 2 次'], ['解析一次', '错误到结束,查询 1 次'], ['不缓存', '0 错误,700 次查询']], ['解析一次'])),
    step("SRV 的优先级与权重。三个目标:A(优先级 10,权重 1)、B(10,权重 3)、C(20,权重 5)。按 RFC 2782 选 10000 次:A 2478 次(24.8%)、B 7522 次(75.2%)、C 0 次——优先级更高(数字更小)的目标在时,低优先级的得不到流量,同优先级内按权重 1 : 3 分。把 A、B 从 DNS 里删掉后再选 10000 次:C 10000 次(100.0%),备用目标接管全部流量。SRV 本身不含健康状态,“都挂了”要靠有人把它们从区域里删掉。", t=tl(S(2)), mark=lidx(S(2), 'A、B 都被删掉'), done=lidx(S(2), 'A、B、C 都在'), b=bars([['A、B、C 都在:A', 24.8, '24.8%'], ['A、B、C 都在:B', 75.2, '75.2%'], ['A、B、C 都在:C', 0, '0%'], ['A、B 删掉后:C', 100, '100%']], 100, done=[0, 1, 2], mark=[3]), kv=KV([['同优先级', '按权重 1 : 3 → 24.8% / 75.2%'], ['低优先级 C', '高优先级在时 0%'], ['高优先级删光', 'C 接管 100%']], ['低优先级 C'])),
    step("负缓存。new.svc.local 还没登记时查询得到 NXDOMAIN,SOA minimum(负缓存 TTL)20 s。client 第 0 秒查询一次(NXDOMAIN),第 2 秒服务上线,之后每 1 s 查询一次。遵守缓存(含负缓存)的客户端:第 20.2 s 才第一次解析成功,上线后过了 18.1 s 才发现,DNS 一共收到 2 次查询。不缓存的客户端:上线后下一次查询(2.0 s)就成功,过了 0.0 s,DNS 收到 3 次查询。“不存在”也是会被缓存的答案,服务晚于客户端的第一次查询才登记时,负缓存 TTL 决定客户端多久能发现它。", t=tl(S(3)), mark=lidx(S(3), '遵守缓存'), done=lidx(S(3), '不缓存'), b=bars([['遵守负缓存:发现用了 s', 18.1, '18.1'], ['不缓存:发现用了 s', 0.0, '0.0'], ['遵守负缓存:DNS 查询', 2, '2'], ['不缓存:DNS 查询', 3, '3']], 18.5, mark=[0], done=[1, 2, 3]), kv=KV([['遵守负缓存', '上线后 18.1 s 才发现(SOA minimum 20 s)'], ['不缓存', '上线后下一次查询就成功']], ['遵守负缓存'])),
    step("UDP 应答放不下。web.svc.local 有 N 个 SRV 目标,查询不带 EDNS(512 字节上限)。N = 5:UDP 应答 5 条记录、241 字节、没有截断。N = 20:UDP 应答 0 条、TC 标志置位、31 字节;用 TCP 重查拿到 20 条、871 字节。N = 40:TCP 1711 字节;N = 100:TCP 4231 字节,UDP 同样被截断。这个服务端在放不下时把答案清空并置 TC 位,让客户端改用 TCP(有的服务端会保留放得下的部分)。实例数多的服务不适合只靠一个 SRV 记录集合。", t=tl(S(4)), mark=lidx(S(4), '20    |', '100   |'), done=lidx(S(4), '5     |'), b=bars([['N = 5:UDP 应答字节', 241, '241(不截断)'], ['N = 20:TCP 应答字节', 871, '871(UDP 被截断)'], ['N = 100:TCP 应答字节', 4231, '4231'], ['N = 20 以上:UDP 应答字节', 31, '31(TC 置位,0 条)']], 4300, done=[0], mark=[1, 2, 3]), kv=KV([['N ≤ 5', 'UDP 够用'], ['N ≥ 20', 'UDP 被截断(TC),要 TCP 重查'], ['N = 100', 'TCP 应答 4231 字节']], ['N ≥ 20'])),
]
